def triple_barrier_label(prices, entry_idx, pt_mult, sl_mult, vol, max_holding):
    entry_price = prices[entry_idx]
    upper = entry_price * (1 + pt_mult * vol)
    lower = entry_price * (1 - sl_mult * vol)
    last_idx = min(entry_idx + max_holding, len(prices) - 1)

    for i in range(entry_idx + 1, last_idx + 1):
        if prices[i] >= upper:
            return 1, i          # upper barrier touched first
        if prices[i] <= lower:
            return -1, i         # lower barrier touched first

    ret = prices[last_idx] / entry_price - 1
    label = 1 if ret > 0 else -1 if ret < 0 else 0
    return label, last_idx       # vertical barrier reached
